      const local = (day ? k : 0.034 * k) * here.T[1] * Math.max(sinEl, 0.04) + (0.06 * dn2 + 4e-3);
      this.localLum = local;
      U.uStarK.value = clamp2(1.2 - local * 5.5, 0.05, 1);
